// SPDX-License-Identifier: UNLICENSED
pragma solidity =0.7.6;

import './HistoryStateTrackerBase.sol';
import './interfaces/external/IFlareContractRegistry.sol';
import './interfaces/external/IWNat.sol';
import { Address } from "@openzeppelin/contracts/utils/Address.sol";

/**
 * Copyright (C) 2024 Flare Finance B.V. - All Rights Reserved.
 *
 * This source code and any functionality deriving from it are owned by Flare
 * Finance BV and the use of it is only permitted within the official platforms
 * and/or original products of Flare Finance B.V. and its licensed parties. Any
 * further enquiries regarding this copyright and possible licenses can be directed
 * to partners[at]flr.finance.
 *
 * The source code and any functionality deriving from it are provided "as is",
 * without warranty of any kind, express or implied, including but not limited to
 * the warranties of merchantability, fitness for a particular purpose and
 * noninfringement. In no event shall the authors or copyright holder be liable
 * for any claim, damages or other liability, whether in an action of contract,
 * tort or otherwise, arising in any way out of the use or other dealings or in
 * connection with the source code and any functionality deriving from it.
 */

contract HistoryStateTrackerByBlock is HistoryStateTrackerBase {
    /// @dev The Flare contract registry. The same for all Flare's networks
    IFlareContractRegistry private constant _flareContractRegistry =
        IFlareContractRegistry(0xaD67FE66660Fb8dFE9d6b1b4240d8650e30F6019);

    /// @dev The Flare's WNat contract.
    IWNat internal immutable wnat;

    constructor() {
        address wnatAddress = _flareContractRegistry.getContractAddressByName("WNat");
        require (Address.isContract(wnatAddress), "HistoryStateTracker: WNat address is not a contract");
        wnat = IWNat(wnatAddress);
    }

    /// @notice Initialize the contract
    /// @dev Extra admin is supposed to be EnosysDexV3 factory, that will add the trackable token pools
    /// @param extraAdmin address of the extra admin that can add other role members
    /// @notice extraAdmin can be address(0) if no extra admin is required
    /// @param cleaner address of the cleaner contract to which is assigned CLEANER_ROLE
    function initialize(address extraAdmin, address cleaner) public initializer {
        _initializeHistoryStataTrackerBase(extraAdmin, cleaner);
    }

    /// @inheritdoc HistoryStateTrackerBase
    function getCurrentCheckpointIndex() public view override returns (uint64) {
        return uint64(block.number);
    }

    function getCleanupCheckpointIndex() public view override returns (uint256) {
        return wnat.cleanupBlockNumber();
    }
}

