import {AccessControlUpgradeable} from '@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol';
import {IHistoryStateTrackerBase} from './interfaces/IHistoryStateTrackerBase.sol';
import './libraries/checkpoint/CheckPointsManagerByBytes32.sol';

abstract contract HistoryStateTrackerBase is IHistoryStateTrackerBase, AccessControlUpgradeable {
    using CheckPointsManagerByBytes32 for CheckPointsManagerByBytes32.CheckPointsByBytes32State;

    /// @dev role required to call setCleanupBlockNumber
    bytes32 public constant CLEANER_ROLE = keccak256('CLEANER');
    /// @dev role required to call `updatePositionOnMint` and `updatePositionStateIfNecessary`
    bytes32 public constant UPDATER_ROLE = keccak256('UPDATER');

    // The number of history cleanup steps executed for every write operation.
    // It is more than 1 to make as certain as possible that all history gets cleaned eventually.
    uint256 internal constant CLEANUP_COUNT = 2;

    CheckPointsManagerByBytes32.CheckPointsByBytes32State internal _stateHistory;

    /// Address of the contract that is allowed to call methods for history cleaning.
    address public cleanerContract;

    // Historic data for the epochs before `cleanupEpochNumber` can be erased,
    // history before that epoch should never be used since it can be inconsistent.
    uint256 private cleanupCheckpointIndex;

    /// @dev Modifier that checks that an account has a specific role.
    modifier onlyRole(bytes32 role) {
        address account = _msgSender();
        require(hasRole(role, account), 'HistoryStateTrackerBase: missing role');
        _;
    }

    /// This method cannot be called for `_epochNumber` lower than the current cleanup epoch number.
    modifier notBeforeCleanupEpoch(uint256 _checkpointIndex) {
        require(
            _checkpointIndex >= getCleanupCheckpointIndex(),
            'HistoryStateTrackerBase: reading from cleaned-up epoch'
        );
        _;
    }

    /// @notice Initialize the contract
    /// @param extraAdmin address of the extra admin that can add other role members
    /// @notice extraAdmin can be address(0) if no extra admin is required
    /// @param cleaner address of the cleaner contract to which is assigned CLEANER_ROLE
    function _initializeHistoryStataTrackerBase(address extraAdmin, address cleaner) internal {
        require(cleaner != address(0), 'HistoryStateTrackerBase: cleaner is zero address');
        __AccessControl_init();
        if (extraAdmin != address(0)) {
            _setupRole(DEFAULT_ADMIN_ROLE, extraAdmin);
        }
        _setupRole(CLEANER_ROLE, cleaner);
        _setupRole(DEFAULT_ADMIN_ROLE, _msgSender());
    }

    /// @inheritdoc IHistoryStateTrackerBase
    function getCurrentCheckpointIndex() public view virtual override returns (uint64);

    /// @inheritdoc IHistoryStateTrackerBase
    function updateHistoryState(bytes32 key, uint256 amount) public override onlyRole(UPDATER_ROLE) {
        _updateHistoryState(key, amount, getCurrentCheckpointIndex());
    }

    /// @inheritdoc IHistoryStateTrackerBase
    function setCleanerContract(address _cleanerContract) public override onlyRole(DEFAULT_ADMIN_ROLE) {
        cleanerContract = _cleanerContract;
    }

    /// @inheritdoc IHistoryStateTrackerBase
    function setCleanupCheckpoint(uint256 checkpointIndex) public override onlyRole(DEFAULT_ADMIN_ROLE) {
        require(
            checkpointIndex > cleanupCheckpointIndex,
            'HistoryStateTrackerBase: Cleanup checkpointIndex number must never decrease'
        );
        require(checkpointIndex < getCurrentCheckpointIndex(), 'Cleanup checkpointIndex number must be in the past');
        cleanupCheckpointIndex = checkpointIndex;
    }

    /// @inheritdoc IHistoryStateTrackerBase
    function stateOfAt(
        bytes32 key,
        uint256 checkpointIndex
    ) public view override notBeforeCleanupEpoch(checkpointIndex) returns (uint256) {
        return _stateHistory.valueOfAt(key, uint64(checkpointIndex), getCurrentCheckpointIndex());
    }

    /// @inheritdoc IHistoryStateTrackerBase
    function stateOfAtNow(bytes32 key) public view override returns (uint256) {
        return _stateHistory.valueOfAtNow(key);
    }

    /// @inheritdoc IHistoryStateTrackerBase
    function getCleanupCheckpointIndex() public view virtual override returns (uint256) {
        return cleanupCheckpointIndex;
    }

    /// @inheritdoc IHistoryStateTrackerBase
    function stateHistoryCleanup(bytes32 key, uint256 count) public override onlyRole(CLEANER_ROLE) returns (uint256) {
        return _stateHistory.cleanupOldCheckpoints(key, count, uint64(getCleanupCheckpointIndex()));
    }

    function _updateHistoryState(bytes32 _key, uint256 amount, uint64 checkpointIndex) internal {
        _stateHistory.writeValue(_key, amount, checkpointIndex);
        _stateHistory.cleanupOldCheckpoints(_key, CLEANUP_COUNT, uint64(getCleanupCheckpointIndex()));

        emit UpdateHistoryState(_key, checkpointIndex, amount);
    }

    uint256[47] private __gap;
}

