// https://gitlab.com/flarenetwork/flare-smart-contracts/-/blob/master/contracts/token/lib/CheckPointHistory.sol

import '@openzeppelin/contracts/math/Math.sol';
import '@openzeppelin/contracts/math/SafeMath.sol';
import '@openzeppelin/contracts/utils/SafeCast.sol';

/**
 * @title Check Point History library
 * @notice A contract to manage checkpoints as of a given block.
 * @dev Store value history by block number with detachable state.
 **/
library CheckPointHistory {
    using SafeMath for uint256;
    using SafeCast for uint256;

    /**
     * @dev `CheckPoint` is the structure that attaches a block number to a
     *  given value; the block number attached is the one that last changed the
     *  value
     **/
    struct CheckPoint {
        // `value` is the amount of tokens at a specific block number
        uint256 value;
        // `fromCheckpointIndex` is the block number that the value was generated from
        uint64 fromCheckpointIndex;
    }

    struct CheckPointHistoryState {
        // `checkpoints` is an array that tracks values at non-contiguous block numbers
        mapping(uint256 => CheckPoint) checkpoints;
        // `checkpoints` before `startIndex` have been deleted
        // INVARIANT: checkpoints.endIndex == 0 || startIndex < checkpoints.endIndex      (strict!)
        // startIndex and endIndex are both less then fromBlock, so 64 bits is enough
        uint64 startIndex;
        // the index AFTER last
        uint64 endIndex;
    }

    /**
     * @notice Binary search of _checkpoints array.
     * @param _checkpoints An array of CheckPoint to search.
     * @param _startIndex Smallest possible index to be returned.
     * @param _endIndex Largest possible index to be returned.
     * @param _index The index to search for.
     */
    function _indexOfGreatestIndexLessThan(
        mapping(uint256 => CheckPoint) storage _checkpoints,
        uint256 _startIndex,
        uint256 _endIndex,
        uint256 _index
    ) private view returns (uint256 index) {
        // Binary search of the value by given block number in the array
        uint256 min = _startIndex;
        uint256 max = _endIndex.sub(1);
        while (max > min) {
            uint256 mid = (max.add(min).add(1)).div(2);
            if (_checkpoints[mid].fromCheckpointIndex <= _index) {
                min = mid;
            } else {
                max = mid.sub(1);
            }
        }
        return min;
    }

    /**
     * @notice Queries the value at a specific `_checkpointIndex`
     * @param _self A CheckPointHistoryState instance to manage.
     * @param _checkpointIndex The index to search for.
     * @param _currentCheckpointIndex The current value of index. Required for gas optimization.
     * @return _value The value at `_checkpointIndex`
     **/
    function valueAt(
        CheckPointHistoryState storage _self,
        uint64 _checkpointIndex,
        uint64 _currentCheckpointIndex
    ) internal view returns (uint256 _value) {
        uint256 historyCount = _self.endIndex;

        if (historyCount == 0) return 0;

        // Shortcut for the actual value (extra optimized for current checkpoint, to save one storage read)
        // historyCount - 1 is safe, since historyCount != 0
        if (
            _checkpointIndex >= _currentCheckpointIndex ||
            _checkpointIndex >= _self.checkpoints[historyCount - 1].fromCheckpointIndex
        ) {
            return _self.checkpoints[historyCount - 1].value;
        }

        uint256 startIndex = _self.startIndex;
        if (_checkpointIndex < _self.checkpoints[startIndex].fromCheckpointIndex) {
            // reading data before `startIndex` is only safe before first cleanup
            require(startIndex == 0, 'CheckPointHistory: reading from cleaned-up block');
            return 0;
        }

        // Find the checkpoint with index less than or equal to index given
        uint256 index = _indexOfGreatestIndexLessThan(_self.checkpoints, startIndex, _self.endIndex, _checkpointIndex);

        return _self.checkpoints[index].value;
    }

    /**
     * @notice Queries the value at the last available checkpoint.
     * @param _self A CheckPointHistoryState instance to manage.
     * @return _value The value at the last available checkpoint
     **/
    function valueAtNow(CheckPointHistoryState storage _self) internal view returns (uint256 _value) {
        uint256 historyCount = _self.endIndex;
        // No _checkpoints, return 0
        if (historyCount == 0) return 0;
        // Return last value
        return _self.checkpoints[historyCount - 1].value;
    }

    /**
     * @notice Writes the value at the current block.
     * @param _self A CheckPointHistoryState instance to manage.
     * @param _value Value to write.
     * @param _currentCheckpointIndex Checkpoint index to write the value.
     **/
    function writeValue(
        CheckPointHistoryState storage _self,
        uint256 _value,
        uint64 _currentCheckpointIndex
    ) internal {
        uint256 historyCount = _self.endIndex;
        if (historyCount == 0) {
            //checkpoints is empty, push new CheckPoint
            _self.checkpoints[0] = CheckPoint({fromCheckpointIndex: _currentCheckpointIndex, value: _value});
            _self.endIndex = 1;
        } else {
            // historyCount - 1 is safe, since historyCount != 0
            CheckPoint storage lastCheckpoint = _self.checkpoints[historyCount - 1];
            uint256 lastCheckpointIndex = lastCheckpoint.fromCheckpointIndex;

            if (_currentCheckpointIndex == lastCheckpointIndex) {
                // If last checkpoint is the same as current checkpoint, update the value
                lastCheckpoint.value = _value;
            } else {
                // we should never have future blocks in history
                assert(_currentCheckpointIndex > lastCheckpointIndex);
                // push new CheckPoint
                _self.checkpoints[historyCount] = CheckPoint({
                    fromCheckpointIndex: _currentCheckpointIndex,
                    value: _value
                });
                _self.endIndex = uint64(historyCount + 1); // 64 bit safe, because historyCount <= block.number
            }
        }
    }

    /**
     * Delete at most `_count` of the oldest checkpoints.
     * At least one checkpoint at or before `_cleanupCheckpointIndex` will remain
     * (unless the history was empty to start with).
     */
    function cleanupOldCheckpoints(
        CheckPointHistoryState storage _self,
        uint256 _count,
        uint256 _cleanupCheckpointIndex
    ) internal returns (uint256) {
        if (_cleanupCheckpointIndex == 0) return 0; // optimization for when cleaning is not enabled
        uint256 length = _self.endIndex;
        if (length == 0) return 0;
        uint256 startIndex = _self.startIndex;
        // length - 1 is safe, since length != 0 (check above)
        uint256 endIndex = Math.min(startIndex.add(_count), length - 1); // last element can never be deleted
        uint256 index = startIndex;
        // we can delete `checkpoint[index]` while the next checkpoint is at `_cleanupBlockNumber` or before
        while (index < endIndex && _self.checkpoints[index + 1].fromCheckpointIndex <= _cleanupCheckpointIndex) {
            delete _self.checkpoints[index];
            index++;
        }
        if (index > startIndex) {
            // index is the first not deleted index
            _self.startIndex = index.toUint64();
        }
        return index - startIndex; // safe: index >= startIndex at start and then increases
    }
}

