// This contract was forked from Flare Network Smart Contract repo
// https://gitlab.com/flarenetwork/flare-smart-contracts/-/blob/master/contracts/token/lib/CheckPointsByAddress.sol
// The following changes were made to the code:
// * rename from CheckPointsByAddress to CheckPointsByBytes32
// * state variable historyByAddress was renamed to historyByBytes32
// * state variable historyByBytes32 is now a mapping of bytes32 to CheckPointHistoryState instead of mapping of address to CheckPointHistoryState
// * change everywhere address(es) to bytes32 (including comments)
// * change checks that provided address is zero to check that provided bytes32 is zero


import "./CheckPointHistory.sol";
import "@openzeppelin/contracts/math/SafeMath.sol";

/**
 * @title Check Points By Bytes32 library
 * @notice A contract to manage checkpoint history for a collection of bytes32.
 * @dev Store value history by bytes32, and then by block number.
 **/ 
library CheckPointsManagerByBytes32 {
    using SafeMath for uint256;
    using CheckPointHistory for CheckPointHistory.CheckPointHistoryState;

    struct CheckPointsByBytes32State {
        // `historyByBytes32` is the map that stores the check point history of each bytes32
        mapping(bytes32 => CheckPointHistory.CheckPointHistoryState) historyByBytes32;
    }

    /**
     * @notice Send `amount` value to `to` bytes32 from `from` bytes32.
     * @param _self A CheckPointsByBytes32State instance to manage.
     * @param _from bytes32 of the history of from values 
     * @param _to bytes32 of the history of to values 
     * @param _amount The amount of value to be transferred
     * @param _currentCheckpointIndex The current value of index. Required for gas optimization.
     **/
    function transmit(
        CheckPointsByBytes32State storage _self, 
        bytes32 _from, 
        bytes32 _to, 
        uint256 _amount,
        uint64 _currentCheckpointIndex
    )
        internal
    {
        // Shortcut
        if (_amount == 0) return;

        // Update transferer value, compute the new from balance
        uint256 newValueFrom = valueOfAtNow(_self, _from).sub(_amount);
        writeValue(_self, _from, newValueFrom, _currentCheckpointIndex);

        // Update transferee value, compute the new to balance
        uint256 newValueTo = valueOfAtNow(_self, _to).add(_amount);
        writeValue(_self, _to, newValueTo, _currentCheckpointIndex);
    }

        /**
     * @notice Queries the value of `_owner` at a specific `_blockNumber`.
     * @param _self A CheckPointsByBytes32State instance to manage.
     * @param _owner The bytes32 from which the value will be retrieved.
     * @param _checkpointIndex The block number to query for the then current value.
     * @param _currentCheckpointIndex The current value of index. Required for gas optimization.
     * @return The value at `_blockNumber` for `_owner`.
     **/
    function valueOfAt(
        CheckPointsByBytes32State storage _self, 
        bytes32 _owner, 
        uint64 _checkpointIndex, 
        uint64 _currentCheckpointIndex
    )
        internal view
        returns (uint256)
    {
        // Get history for _owner
        CheckPointHistory.CheckPointHistoryState storage history = _self.historyByBytes32[_owner];
        // Return value at given block
        return history.valueAt(_checkpointIndex, _currentCheckpointIndex);
    }

    /**
     * @notice Get the value of the `_owner` at the current `block.number`.
     * @param _self A CheckPointsByBytes32State instance to manage.
     * @param _owner The bytes32 of the value is being requested.
     * @return The value of `_owner` at the current block.
     **/
    function valueOfAtNow(CheckPointsByBytes32State storage _self, bytes32 _owner) internal view returns (uint256) {
        // Get history for _owner
        CheckPointHistory.CheckPointHistoryState storage history = _self.historyByBytes32[_owner];
        // Return value at now
        return history.valueAtNow();
    }

    /**
     * @notice Writes the `value` at the current block number for `_owner`.
     * @param _self A CheckPointsByBytesState instance to manage.
     * @param _owner The bytes32 of `_owner` to write.
     * @param _value The value to write.
     * @param _currentCheckpointIndex Checkpoint index to write the value.
     * @dev Sender must be the owner of the contract.
     **/
    function writeValue(
        CheckPointsByBytes32State storage _self, 
        bytes32 _owner, 
        uint256 _value,
        uint64 _currentCheckpointIndex
    )
        internal
    {
        // Get history for _owner
        CheckPointHistory.CheckPointHistoryState storage history = _self.historyByBytes32[_owner];
        // Write the value
        history.writeValue(_value, _currentCheckpointIndex);
    }

    /**
     * Delete at most `_count` of the oldest checkpoints.
     * At least one checkpoint at or before `_cleanupCheckpointIndex` will remain 
     * (unless the history was empty to start with).
     */    
    function cleanupOldCheckpoints(
        CheckPointsByBytes32State storage _self, 
        bytes32 _owner, 
        uint256 _count,
        uint64 _cleanupCheckpointIndex
    )
        internal
        returns (uint256)
    {
        return _self.historyByBytes32[_owner].cleanupOldCheckpoints(_count, _cleanupCheckpointIndex);
    }
}
